package org.opengridseg.image;
public final class RotatedImage { private final FloatPlane plane; private final double angle,sourceCx,sourceCy,rotatedCx,rotatedCy;private final int sourceWidth,sourceHeight; RotatedImage(FloatPlane plane,double angle,double sourceCx,double sourceCy,double rotatedCx,double rotatedCy,int sourceWidth,int sourceHeight){this.plane=plane;this.angle=angle;this.sourceCx=sourceCx;this.sourceCy=sourceCy;this.rotatedCx=rotatedCx;this.rotatedCy=rotatedCy;this.sourceWidth=sourceWidth;this.sourceHeight=sourceHeight;} public FloatPlane plane(){return plane;}public double angleDegrees(){return angle;}public int sourceWidth(){return sourceWidth;}public int sourceHeight(){return sourceHeight;} public double[] toOriginal(double x,double y){double a=Math.toRadians(angle),u=x-rotatedCx,v=y-rotatedCy;return new double[]{sourceCx+Math.cos(a)*u-Math.sin(a)*v,sourceCy+Math.sin(a)*u+Math.cos(a)*v};} public double[] toRotated(double x,double y){double a=Math.toRadians(angle),dx=x-sourceCx,dy=y-sourceCy;return new double[]{rotatedCx+Math.cos(a)*dx+Math.sin(a)*dy,rotatedCy-Math.sin(a)*dx+Math.cos(a)*dy};} }
